      line-height: 1.5;
    }

    .form-field {
      display: flex;
      gap: 12px;
      align-items: flex-start;
      padding: 16px;
      border: 1px solid rgba(148, 163, 184, 0.16);
      border-radius: 16px;
      background: rgba(15, 23, 42, 0.72);
    }

    .checkbox-wrap {
      display: flex;
      align-items: center;
      justify-content: center;
      width: 22px;
      height: 22px;
      flex: 0 0 auto;
      margin-top: 1px;
    }

    input[type="checkbox"] {
      width: 18px;
      height: 18px;
      margin: 0;
      accent-color: var(--accent);
      cursor: pointer;
    }

    .field-copy {
      display: grid;
      gap: 4px;
    }

    label {
      font-weight: 600;
      cursor: pointer;
    }

    .helper {
      color: var(--muted);
      font-size: 0.95rem;
      line-height: 1.45;
    }

    .actions {
      margin-top: 22px;
    }

    button {
      width: 100%;
      border: 0;
      border-radius: 14px;
      padding: 14px 18px;
      background: linear-gradient(135deg, var(--accent), var(--accent-2));
      color: white;
      font: inherit;
      font-weight: 700;
      cursor: pointer;
      box-shadow: 0 12px 30px rgba(124, 58, 237, 0.28);
      transition: transform 0.15s ease, box-shadow 0.15s ease, opacity 0.15s ease;
    }

    button:hover {
      transform: translateY(-1px);
      box-shadow: 0 16px 36px rgba(124, 58, 237, 0.34);
    }

    button:focus-visible,
    input[type="checkbox"]:focus-visible {
      outline: 3px solid var(--focus);
      outline-offset: 3px;
    }

    .status {
      min-height: 1.25em;
      margin-top: 14px;
      color: #c4b5fd;
      font-size: 0.95rem;
    }
  </style>
</head>
<body>
  <main class="card">
    <h1>Terms of Use Consent</h1>
    <p>Please review and confirm your agreement before continuing.</p>

    <form id="consent-form" novalidate>
      <div class="form-field">
        <div class="checkbox-wrap">
          <input id="consent" name="consent" type="checkbox" required>
        </div>
        <div class="field-copy">
          <label for="consent">I agree to the terms of use.</label>
          <span class="helper">You must accept these terms to submit the form.</span>
        </div>
      </div>

      <div class="actions">
        <button type="submit">Submit</button>
      </div>

      <div class="status" id="status" aria-live="polite"></div>
    </form>
  </main>

  <script>
    const form = document.getElementById('consent-form');
    const status = document.getElementById('status');
    const checkbox = document.getElementById('consent');

